/* @lc app=leetcode id=1750 lang=kotlin */ class Solution { fun minimumLength(s: String): Int = generateSequence(0 to s.length - 1) { (l, r) -> if (l < r && s[l] == s[r]) (generateSequence(l) { it + 1 }.takeWhile { it <= r && s[it] == s[l] }.last() + 1) to (generateSequence(r) { it - 1 }.takeWhile { it >= l && s[it] == s[r] }.last() - 1) else null }.last().let { (l, r) -> maxOf(0, r - l + 1) } }